   141→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
   142→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   143→	checkpoint := incrementalCheckpointData{
   144→		Type:      opts.IncrementalType,
   145→		ToolUseID: opts.ToolUseID,
   146→		Timestamp: time.Now().UTC(),
   147→		Data:      opts.IncrementalData,
   148→	}
   149→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   150→	if err != nil {
   151→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
   152→	}
   153→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
   154→	if err != nil {
   155→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
   156→	}
   157→
   158→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
   159→	cpPath := taskPath + "checkpoints/" + cpFilename
   160→	entries[cpPath] = object.TreeEntry{
   161→		Name: cpPath,
   162→		Mode: filemode.Regular,
   163→		Hash: cpBlobHash,
   164→	}
   165→	return cpPath, nil
   166→}
