   339→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
   340→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingSummary *CheckpointSummary, sessionFilePaths SessionFilePaths) error {
   341→	summary := CheckpointSummary{
   342→		CheckpointID:     opts.CheckpointID,
   343→		Strategy:         opts.Strategy,
   344→		Branch:           opts.Branch,
   345→		CheckpointsCount: opts.CheckpointsCount,
   346→		FilesTouched:     opts.FilesTouched,
   347→		Sessions:         []SessionFilePaths{sessionFilePaths},
   348→		TokenUsage:       opts.TokenUsage,
   349→	}
   350→
   351→	// Aggregate with existing summary if present
   352→	if existingSummary != nil {
   353→		summary.CheckpointsCount = existingSummary.CheckpointsCount + opts.CheckpointsCount
   354→		summary.FilesTouched = mergeFilesTouched(existingSummary.FilesTouched, opts.FilesTouched)
   355→		summary.TokenUsage = aggregateTokenUsage(existingSummary.TokenUsage, opts.TokenUsage)
   356→
   357→		// Copy existing sessions and append new session
   358→		summary.Sessions = make([]SessionFilePaths, len(existingSummary.Sessions)+1)
   359→		copy(summary.Sessions, existingSummary.Sessions)
   360→		summary.Sessions[len(existingSummary.Sessions)] = sessionFilePaths
   361→	}
   362→
   363→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
   364→	if err != nil {
   365→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
   366→	}
   367→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   368→	if err != nil {
   369→		return err
   370→	}
   371→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   372→		Name: basePath + paths.MetadataFileName,
   373→		Mode: filemode.Regular,
   374→		Hash: metadataHash,
   375→	}
   376→	return nil
   377→}
