   379→// readJSONFromBlob reads JSON from a blob hash and decodes it to the given type.
   380→func readJSONFromBlob[T any](repo *git.Repository, hash plumbing.Hash) (*T, error) {
   381→	blob, err := repo.BlobObject(hash)
   382→	if err != nil {
   383→		return nil, fmt.Errorf("failed to get blob: %w", err)
   384→	}
   385→
   386→	reader, err := blob.Reader()
   387→	if err != nil {
   388→		return nil, fmt.Errorf("failed to get blob reader: %w", err)
   389→	}
   390→	defer reader.Close()
   391→
   392→	var result T
   393→	if err := json.NewDecoder(reader).Decode(&result); err != nil {
   394→		return nil, fmt.Errorf("failed to decode: %w", err)
   395→	}
   396→
   397→	return &result, nil
   398→}
