   405→// aggregateTokenUsage sums two TokenUsage structs.
   406→// Returns nil if both inputs are nil.
   407→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
   408→	if a == nil && b == nil {
   409→		return nil
   410→	}
   411→	result := &agent.TokenUsage{}
   412→	if a != nil {
   413→		result.InputTokens = a.InputTokens
   414→		result.CacheCreationTokens = a.CacheCreationTokens
   415→		result.CacheReadTokens = a.CacheReadTokens
   416→		result.OutputTokens = a.OutputTokens
   417→		result.APICallCount = a.APICallCount
   418→	}
   419→	if b != nil {
   420→		result.InputTokens += b.InputTokens
   421→		result.CacheCreationTokens += b.CacheCreationTokens
   422→		result.CacheReadTokens += b.CacheReadTokens
   423→		result.OutputTokens += b.OutputTokens
   424→		result.APICallCount += b.APICallCount
   425→	}
   426→	return result
   427→}
