   429→// writeTranscript writes the transcript file from in-memory content or file path.
   430→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   431→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   432→	transcript := opts.Transcript
   433→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   434→		var readErr error
   435→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   436→		if readErr != nil {
   437→			// Non-fatal: transcript may not exist yet
   438→			transcript = nil
   439→		}
   440→	}
   441→	if len(transcript) == 0 {
   442→		return nil
   443→	}
   444→
   445→	// Chunk the transcript if it's too large
   446→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   447→	if err != nil {
   448→		return fmt.Errorf("failed to chunk transcript: %w", err)
   449→	}
   450→
   451→	// Write chunk files
   452→	for i, chunk := range chunks {
   453→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   454→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   455→		if err != nil {
   456→			return err
   457→		}
   458→		entries[chunkPath] = object.TreeEntry{
   459→			Name: chunkPath,
   460→			Mode: filemode.Regular,
   461→			Hash: blobHash,
   462→		}
   463→	}
   464→
   465→	// Content hash for deduplication (hash of full transcript)
   466→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   467→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   468→	if err != nil {
   469→		return err
   470→	}
   471→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   472→		Name: basePath + paths.ContentHashFileName,
   473→		Mode: filemode.Regular,
   474→		Hash: hashBlob,
   475→	}
   476→	return nil
   477→}
