   479→// mergeFilesTouched combines two file lists, removing duplicates.
   480→func mergeFilesTouched(existing, additional []string) []string {
   481→	seen := make(map[string]bool)
   482→	var result []string
   483→
   484→	for _, f := range existing {
   485→		if !seen[f] {
   486→			seen[f] = true
   487→			result = append(result, f)
   488→		}
   489→	}
   490→	for _, f := range additional {
   491→		if !seen[f] {
   492→			seen[f] = true
   493→			result = append(result, f)
   494→		}
   495→	}
   496→
   497→	sort.Strings(result)
   498→	return result
   499→}
