   506→// archiveExistingSession moves existing session files to a numbered subfolder.
   507→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   508→func (s *GitStore) archiveExistingSession(basePath string, sessionCount int, entries map[string]object.TreeEntry) {
   509→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   510→
   511→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   512→	filesToArchive := []string{
   513→		paths.MetadataFileName,
   514→		paths.TranscriptFileName,
   515→		paths.PromptFileName,
   516→		paths.ContextFileName,
   517→		paths.ContentHashFileName,
   518→	}
   519→
   520→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   521→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   522→	for srcPath := range entries {
   523→		if strings.HasPrefix(srcPath, chunkPrefix) {
   524→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   525→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   526→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   527→			}
   528→		}
   529→	}
   530→
   531→	// Move each file to archive folder
   532→	for _, filename := range filesToArchive {
   533→		srcPath := basePath + filename
   534→		if entry, exists := entries[srcPath]; exists {
   535→			// Add to archive location
   536→			dstPath := archivePath + filename
   537→			entries[dstPath] = object.TreeEntry{
   538→				Name: dstPath,
   539→				Mode: entry.Mode,
   540→				Hash: entry.Hash,
   541→			}
   542→			// Remove from original location (will be overwritten by new session)
   543→			delete(entries, srcPath)
   544→		}
   545→	}
   546→}
