   548→// buildCommitMessage constructs the commit message with proper trailers.
   549→// The commit subject is always "Checkpoint: <id>" for consistency.
   550→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   551→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   552→	var commitMsg strings.Builder
   553→
   554→	// Subject line is always the checkpoint ID for consistent formatting
   555→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   556→
   557→	// Include custom description in body if provided (e.g., task checkpoint details)
   558→	if opts.CommitSubject != "" {
   559→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   560→	}
   561→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   562→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   563→	if opts.Agent != "" {
   564→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   565→	}
   566→	if opts.EphemeralBranch != "" {
   567→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   568→	}
   569→	if taskMetadataPath != "" {
   570→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   571→	}
   572→
   573→	return commitMsg.String()
   574→}
