   594→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   595→// Returns nil, nil if the checkpoint doesn't exist.
   596→//
   597→// The storage format uses numbered subdirectories for each session (0-based):
   598→//
   599→//	<checkpoint-id>/
   600→//	├── metadata.json      # CheckpointSummary with sessions map
   601→//	├── 0/                 # First session
   602→//	│   ├── metadata.json  # Session-specific metadata
   603→//	│   └── full.jsonl     # Transcript
   604→//	├── 1/                 # Second session
   605→//	└── ...
   606→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   607→	_ = ctx // Reserved for future use
   608→
   609→	tree, err := s.getSessionsBranchTree()
   610→	if err != nil {
   611→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   612→	}
   613→
   614→	checkpointPath := checkpointID.Path()
   615→	checkpointTree, err := tree.Tree(checkpointPath)
   616→	if err != nil {
   617→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   618→	}
   619→
   620→	result := &ReadCommittedResult{}
   621→
   622→	// Read root metadata.json as CheckpointSummary
   623→	var summary CheckpointSummary
   624→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   625→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   626→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   627→			json.Unmarshal([]byte(content), &summary)
   628→		}
   629→	}
   630→
   631→	// Convert CheckpointSummary to CommittedMetadata for backwards compatibility
   632→	// Note: Agent and SessionID are derived from session-level metadata
   633→	result.Metadata = CommittedMetadata{
   634→		CheckpointID:     summary.CheckpointID,
   635→		Strategy:         summary.Strategy,
   636→		Branch:           summary.Branch,
   637→		CheckpointsCount: summary.CheckpointsCount,
   638→		FilesTouched:     summary.FilesTouched,
   639→		TokenUsage:       summary.TokenUsage,
   640→	}
   641→
   642→	// Read data from the appropriate session subdirectories
   643→	if len(summary.Sessions) > 0 {
   644→		// Find the latest session index (highest numbered directory, 0-based)
   645→		latestIndex := len(summary.Sessions) - 1
   646→
   647→		// Read latest session data
   648→		latestDir := strconv.Itoa(latestIndex)
   649→		if latestTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   650→			// Get agent type and session info from session-specific metadata
   651→			var agentType agent.AgentType
   652→			if sessionMetadataFile, fileErr := latestTree.File(paths.MetadataFileName); fileErr == nil {
   653→				if content, contentErr := sessionMetadataFile.Contents(); contentErr == nil {
   654→					var sessionMetadata CommittedMetadata
   655→					if jsonErr := json.Unmarshal([]byte(content), &sessionMetadata); jsonErr == nil {
   656→						agentType = sessionMetadata.Agent
   657→						// Set fields derived from session metadata
   658→						result.Metadata.Agent = sessionMetadata.Agent
   659→						result.Metadata.SessionID = sessionMetadata.SessionID
   660→						result.Metadata.CreatedAt = sessionMetadata.CreatedAt
   661→					}
   662→				}
   663→			}
   664→
   665→			// Read transcript
   666→			if transcript, transcriptErr := readTranscriptFromTree(latestTree, agentType); transcriptErr == nil && transcript != nil {
   667→				result.Transcript = transcript
   668→			}
   669→
   670→			// Read prompts
   671→			if file, fileErr := latestTree.File(paths.PromptFileName); fileErr == nil {
   672→				if content, contentErr := file.Contents(); contentErr == nil {
   673→					result.Prompts = content
   674→				}
   675→			}
   676→
   677→			// Read context
   678→			if file, fileErr := latestTree.File(paths.ContextFileName); fileErr == nil {
   679→				if content, contentErr := file.Contents(); contentErr == nil {
   680→					result.Context = content
   681→				}
   682→			}
   683→		}
   684→
   685→		// Read archived sessions (all except the latest)
   686→		result.ArchivedSessions = s.readArchivedSessionsFromSummary(checkpointTree, summary)
   687→	}
   688→
   689→	return result, nil
   690→}
   691→
   692→// readArchivedSessionsFromSummary reads transcript data from archived session subdirectories using the sessions array.
   693→// Returns sessions ordered by folder index (oldest first), excluding the latest session.
   694→func (s *GitStore) readArchivedSessionsFromSummary(checkpointTree *object.Tree, summary CheckpointSummary) []ArchivedSession {
   695→	var archived []ArchivedSession
   696→
   697→	// Iterate through all sessions except the latest (0-based indexing)
   698→	// Sessions are in folders 0, 1, ..., N-1 where N-1 is the latest
   699→	sessionCount := len(summary.Sessions)
   700→	for i := range sessionCount - 1 {
   701→		folderName := strconv.Itoa(i)
   702→
   703→		// Try to get the session subtree
   704→		subTree, err := checkpointTree.Tree(folderName)
   705→		if err != nil {
   706→			continue // Folder doesn't exist, skip
   707→		}
   708→
   709→		session := ArchivedSession{
   710→			FolderIndex: i,
   711→		}
   712→
   713→		// Get agent type from session metadata
   714→		var agentType agent.AgentType
   715→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   716→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   717→				var metadata CommittedMetadata
   718→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   719→					session.SessionID = metadata.SessionID
   720→					agentType = metadata.Agent
   721→				}
   722→			}
   723→		}
   724→
   725→		// Read transcript (handles both chunked and non-chunked formats)
   726→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   727→			session.Transcript = transcript
   728→		}
   729→
   730→		// Read prompts
   731→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   732→			if content, contentErr := file.Contents(); contentErr == nil {
   733→				session.Prompts = content
   734→			}
   735→		}
   736→
   737→		// Only add if we got a transcript
   738→		if len(session.Transcript) > 0 {
   739→			archived = append(archived, session)
   740→		}
   741→	}
   742→
   743→	return archived
   744→}
