   746→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   747→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   748→//
   749→
   750→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   751→	_ = ctx // Reserved for future use
   752→
   753→	tree, err := s.getSessionsBranchTree()
   754→	if err != nil {
   755→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   756→	}
   757→
   758→	var checkpoints []CommittedInfo
   759→
   760→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   761→	for _, bucketEntry := range tree.Entries {
   762→		if bucketEntry.Mode != filemode.Dir {
   763→			continue
   764→		}
   765→		// Bucket should be 2 hex chars
   766→		if len(bucketEntry.Name) != 2 {
   767→			continue
   768→		}
   769→
   770→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   771→		if treeErr != nil {
   772→			continue
   773→		}
   774→
   775→		// Each entry in the bucket is the remaining part of the checkpoint ID
   776→		for _, checkpointEntry := range bucketTree.Entries {
   777→			if checkpointEntry.Mode != filemode.Dir {
   778→				continue
   779→			}
   780→
   781→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   782→			if cpTreeErr != nil {
   783→				continue
   784→			}
   785→
   786→			// Reconstruct checkpoint ID: <bucket><remaining>
   787→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   788→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   789→			if cpIDErr != nil {
   790→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   791→				continue
   792→			}
   793→
   794→			info := CommittedInfo{
   795→				CheckpointID: checkpointID,
   796→			}
   797→
   798→			// Get details from root metadata file (CheckpointSummary format)
   799→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   800→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   801→					var summary CheckpointSummary
   802→					if err := json.Unmarshal([]byte(content), &summary); err == nil {
   803→						info.CheckpointsCount = summary.CheckpointsCount
   804→						info.FilesTouched = summary.FilesTouched
   805→						info.SessionCount = len(summary.Sessions)
   806→
   807→						// Read session metadata from latest session to get Agent, SessionID, CreatedAt
   808→						if len(summary.Sessions) > 0 {
   809→							latestIndex := len(summary.Sessions) - 1
   810→							latestDir := strconv.Itoa(latestIndex)
   811→							if sessionTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   812→								if sessionMetadataFile, smErr := sessionTree.File(paths.MetadataFileName); smErr == nil {
   813→									if sessionContent, scErr := sessionMetadataFile.Contents(); scErr == nil {
   814→										var sessionMetadata CommittedMetadata
   815→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   816→											info.Agent = sessionMetadata.Agent
   817→											info.SessionID = sessionMetadata.SessionID
   818→											info.CreatedAt = sessionMetadata.CreatedAt
   819→										}
   820→									}
   821→								}
   822→							}
   823→						}
   824→					}
   825→				}
   826→			}
   827→
   828→			checkpoints = append(checkpoints, info)
   829→		}
   830→	}
   831→
   832→	// Sort by time (most recent first)
   833→	sort.Slice(checkpoints, func(i, j int) bool {
   834→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   835→	})
   836→
   837→	return checkpoints, nil
   838→}
