   840→// GetTranscript retrieves the transcript for a specific checkpoint ID.
   841→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
   842→	result, err := s.ReadCommitted(ctx, checkpointID)
   843→	if err != nil {
   844→		return nil, err
   845→	}
   846→	if result == nil {
   847→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
   848→	}
   849→	if len(result.Transcript) == 0 {
   850→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
   851→	}
   852→	return result.Transcript, nil
   853→}
