   855→// GetSessionLog retrieves the session transcript and session ID for a checkpoint.
   856→// This is the primary method for looking up session logs by checkpoint ID.
   857→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   858→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   859→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   860→	result, err := s.ReadCommitted(context.Background(), cpID)
   861→	if err != nil {
