   997→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
   998→// Falls back to origin/entire/sessions if the local branch doesn't exist.
   999→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
  1000→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
  1001→	ref, err := s.repo.Reference(refName, true)
  1002→	if err != nil {
  1003→		// Local branch doesn't exist, try remote-tracking branch
  1004→		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
  1005→		ref, err = s.repo.Reference(remoteRefName, true)
  1006→		if err != nil {
  1007→			return nil, fmt.Errorf("sessions branch not found: %w", err)
  1008→		}
  1009→	}
  1010→
  1011→	commit, err := s.repo.CommitObject(ref.Hash())
  1012→	if err != nil {
  1013→		return nil, fmt.Errorf("failed to get commit object: %w", err)
  1014→	}
  1015→
  1016→	tree, err := commit.Tree()
  1017→	if err != nil {
  1018→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
  1019→	}
  1020→
  1021→	return tree, nil
  1022→}
