  1024→// CreateBlobFromContent creates a blob object from in-memory content.
  1025→// Exported for use by strategy package (session_test.go)
  1026→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1027→	obj := repo.Storer.NewEncodedObject()
  1028→	obj.SetType(plumbing.BlobObject)
  1029→	obj.SetSize(int64(len(content)))
  1030→
  1031→	writer, err := obj.Writer()
  1032→	if err != nil {
  1033→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1034→	}
  1035→
  1036→	_, err = writer.Write(content)
  1037→	if err != nil {
  1038→		_ = writer.Close()
  1039→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1040→	}
  1041→	if err := writer.Close(); err != nil {
  1042→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1043→	}
  1044→
  1045→	hash, err := repo.Storer.SetEncodedObject(obj)
  1046→	if err != nil {
  1047→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1048→	}
  1049→	return hash, nil
  1050→}
