  1052→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1053→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1054→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1055→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1056→		if err != nil {
  1057→			return err
  1058→		}
  1059→		if info.IsDir() {
  1060→			return nil
  1061→		}
  1062→
  1063→		// Skip symlinks to prevent reading files outside the metadata directory.
  1064→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1065→		// then be captured in the checkpoint and stored in git history.
  1066→		if info.Mode()&os.ModeSymlink != 0 {
  1067→			return nil
  1068→		}
  1069→
  1070→		// Get relative path within metadata dir
  1071→		relPath, err := filepath.Rel(metadataDir, path)
  1072→		if err != nil {
  1073→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1074→		}
  1075→
  1076→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1077→		if strings.HasPrefix(relPath, "..") {
  1078→			return fmt.Errorf("path traversal detected: %s", relPath)
  1079→		}
  1080→
  1081→		// Create blob from file
  1082→		blobHash, mode, err := createBlobFromFile(s.repo, path)
  1083→		if err != nil {
  1084→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1085→		}
  1086→
  1087→		// Store at checkpoint path
  1088→		fullPath := basePath + relPath
  1089→		entries[fullPath] = object.TreeEntry{
  1090→			Name: fullPath,
  1091→			Mode: mode,
  1092→			Hash: blobHash,
  1093→		}
  1094→
  1095→		return nil
  1096→	})
  1097→	if err != nil {
  1098→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1099→	}
  1100→	return nil
  1101→}
