  1123→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1124→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1125→// The agentType is used for reassembling chunks in the correct format.
  1126→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1127→	// Collect all transcript-related files
  1128→	var chunkFiles []string
  1129→	var hasBaseFile bool
  1130→
  1131→	for _, entry := range tree.Entries {
  1132→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1133→			hasBaseFile = true
  1134→		}
  1135→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1136→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1137→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1138→			if idx > 0 {
  1139→				chunkFiles = append(chunkFiles, entry.Name)
  1140→			}
  1141→		}
  1142→	}
  1143→
  1144→	// If we have chunk files, read and reassemble them
  1145→	if len(chunkFiles) > 0 {
  1146→		// Sort chunk files by index
  1147→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1148→
  1149→		// Check if base file should be included as chunk 0.
  1150→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1151→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1152→		if hasBaseFile {
  1153→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1154→		}
  1155→
  1156→		var chunks [][]byte
  1157→		for _, chunkFile := range chunkFiles {
  1158→			file, err := tree.File(chunkFile)
  1159→			if err != nil {
  1160→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1161→					slog.String("chunk_file", chunkFile),
  1162→					slog.String("error", err.Error()),
  1163→				)
  1164→				continue
  1165→			}
  1166→			content, err := file.Contents()
  1167→			if err != nil {
  1168→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1169→					slog.String("chunk_file", chunkFile),
  1170→					slog.String("error", err.Error()),
  1171→				)
  1172→				continue
  1173→			}
  1174→			chunks = append(chunks, []byte(content))
  1175→		}
  1176→
  1177→		if len(chunks) > 0 {
  1178→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1179→			if err != nil {
  1180→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1181→			}
  1182→			return result, nil
  1183→		}
  1184→	}
  1185→
  1186→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1187→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1188→		if content, err := file.Contents(); err == nil {
  1189→			return []byte(content), nil
  1190→		}
  1191→	}
  1192→
  1193→	// Try legacy filename
  1194→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1195→		if content, err := file.Contents(); err == nil {
  1196→			return []byte(content), nil
  1197→		}
  1198→	}
  1199→
  1200→	return nil, nil
  1201→}
