   619→// RestoreLogsOnly restores session logs from a logs-only rewind point.
   620→// This fetches the transcript from entire/sessions and writes it to Claude's project directory.
   621→// Does not modify the working directory.
   622→// When multiple sessions were condensed to the same checkpoint, ALL sessions are restored.
   623→// If force is false, prompts for confirmation when local logs have newer timestamps.
   624→func (s *ManualCommitStrategy) RestoreLogsOnly(point RewindPoint, force bool) error {
   625→	if !point.IsLogsOnly {
   626→		return errors.New("not a logs-only rewind point")
   627→	}
   628→
   629→	if point.CheckpointID.IsEmpty() {
   630→		return errors.New("missing checkpoint ID")
   631→	}
   632→
   633→	// Get checkpoint store
   634→	store, err := s.getCheckpointStore()
   635→	if err != nil {
   636→		return fmt.Errorf("failed to get checkpoint store: %w", err)
   637→	}
   638→
   639→	// Read full checkpoint data including archived sessions
   640→	result, err := store.ReadCommitted(context.Background(), point.CheckpointID)
   641→	if err != nil {
   642→		return fmt.Errorf("failed to read checkpoint: %w", err)
   643→	}
   644→	if result == nil {
   645→		return fmt.Errorf("checkpoint not found: %s", point.CheckpointID)
   646→	}
   647→	if len(result.Transcript) == 0 {
   648→		return fmt.Errorf("no transcript found for checkpoint: %s", point.CheckpointID)
   649→	}
   650→
   651→	// Get repo root for Claude project path lookup
   652→	repoRoot, err := paths.RepoRoot()
   653→	if err != nil {
   654→		return fmt.Errorf("failed to get repository root: %w", err)
   655→	}
   656→
   657→	claudeProjectDir, err := paths.GetClaudeProjectDir(repoRoot)
   658→	if err != nil {
   659→		return fmt.Errorf("failed to get Claude project directory: %w", err)
   660→	}
   661→
   662→	// Ensure project directory exists
   663→	if err := os.MkdirAll(claudeProjectDir, 0o750); err != nil {
   664→		return fmt.Errorf("failed to create Claude project directory: %w", err)
   665→	}
   666→
   667→	// Check for newer local logs if not forcing
   668→	if !force {
   669→		sessions := s.classifySessionsForRestore(claudeProjectDir, result)
   670→		hasConflicts := false
   671→		for _, sess := range sessions {
   672→			if sess.Status == StatusLocalNewer {
   673→				hasConflicts = true
   674→				break
   675→			}
   676→		}
   677→		if hasConflicts {
   678→			shouldOverwrite, promptErr := PromptOverwriteNewerLogs(sessions)
   679→			if promptErr != nil {
   680→				return promptErr
   681→			}
   682→			if !shouldOverwrite {
   683→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session logs preserved.\n")
   684→				return nil
   685→			}
   686→		}
   687→	}
   688→
   689→	// Count sessions to restore
   690→	totalSessions := 1 + len(result.ArchivedSessions)
   691→	if totalSessions > 1 {
   692→		fmt.Fprintf(os.Stderr, "Restoring %d sessions from checkpoint:\n", totalSessions)
   693→	}
   694→
   695→	// Restore archived sessions first (oldest to newest)
   696→	for _, archived := range result.ArchivedSessions {
   697→		if len(archived.Transcript) == 0 {
   698→			continue
   699→		}
   700→
   701→		sessionID := archived.SessionID
   702→		if sessionID == "" {
   703→			// Fallback: can't identify session without ID
   704→			fmt.Fprintf(os.Stderr, "  Warning: archived session %d has no session ID, skipping\n", archived.FolderIndex)
   705→			continue
   706→		}
   707→
   708→		modelSessionID := sessionid.ModelSessionID(sessionID)
   709→		claudeSessionFile := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")
   710→
   711→		// Get first prompt for display
   712→		promptPreview := ExtractFirstPrompt(archived.Prompts)
   713→		if promptPreview != "" {
   714→			fmt.Fprintf(os.Stderr, "  Session %d: %s\n", archived.FolderIndex, promptPreview)
   715→		}
   716→
   717→		fmt.Fprintf(os.Stderr, "    Writing to: %s\n", claudeSessionFile)
   718→		if err := os.WriteFile(claudeSessionFile, archived.Transcript, 0o600); err != nil {
   719→			fmt.Fprintf(os.Stderr, "    Warning: failed to write transcript: %v\n", err)
   720→			continue
   721→		}
   722→	}
   723→
   724→	// Restore the most recent session (at root level)
   725→	sessionID := result.Metadata.SessionID
   726→	if sessionID == "" {
   727→		// Fall back to extracting from commit's Entire-Session trailer
   728→		sessionID = s.extractSessionIDFromCommit(point.ID)
   729→		if sessionID == "" {
   730→			return errors.New("failed to determine session ID for latest session")
   731→		}
   732→	}
   733→
   734→	modelSessionID := sessionid.ModelSessionID(sessionID)
   735→	claudeSessionFile := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")
   736→
   737→	if totalSessions > 1 {
   738→		promptPreview := ExtractFirstPrompt(result.Prompts)
   739→		if promptPreview != "" {
   740→			fmt.Fprintf(os.Stderr, "  Session %d (latest): %s\n", totalSessions, promptPreview)
   741→		}
   742→		fmt.Fprintf(os.Stderr, "    Writing to: %s\n", claudeSessionFile)
   743→	} else {
   744→		fmt.Fprintf(os.Stderr, "Writing transcript to: %s\n", claudeSessionFile)
   745→	}
   746→
   747→	if err := os.WriteFile(claudeSessionFile, result.Transcript, 0o600); err != nil {
   748→		return fmt.Errorf("failed to write transcript: %w", err)
   749→	}
   750→
   751→	return nil
   752→}
