   754→// extractSessionIDFromCommit extracts the session ID from a commit's Entire-Session trailer.
   755→func (s *ManualCommitStrategy) extractSessionIDFromCommit(commitHash string) string {
   756→	repo, err := OpenRepository()
   757→	if err != nil {
   758→		return ""
   759→	}
   760→
   761→	hash, err := repo.ResolveRevision(plumbing.Revision(commitHash))
   762→	if err != nil {
   763→		return ""
   764→	}
   765→
   766→	commit, err := repo.CommitObject(*hash)
   767→	if err != nil {
   768→		return ""
   769→	}
   770→
   771→	// Parse Entire-Session trailer
   772→	sessionID, found := trailers.ParseSession(commit.Message)
   773→	if found {
   774→		return sessionID
   775→	}
   776→
   777→	return ""
   778→}
