   780→// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
   781→// Returns an empty string if the prompt cannot be read.
   782→func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
   783→	// Get the commit and its tree
   784→	commit, err := repo.CommitObject(commitHash)
   785→	if err != nil {
   786→		return ""
   787→	}
   788→
   789→	tree, err := commit.Tree()
   790→	if err != nil {
   791→		return ""
   792→	}
   793→
   794→	// Look for prompt.txt in the metadata directory
   795→	promptPath := metadataDir + "/" + paths.PromptFileName
   796→	promptEntry, err := tree.File(promptPath)
   797→	if err != nil {
   798→		return ""
   799→	}
   800→
   801→	content, err := promptEntry.Contents()
   802→	if err != nil {
   803→		return ""
   804→	}
   805→
   806→	return ExtractFirstPrompt(content)
   807→}
