   809→// SessionRestoreStatus represents the status of a session being restored.
   810→type SessionRestoreStatus int
   811→
   812→const (
   813→	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
   814→	StatusUnchanged                                   // Local and checkpoint are the same
   815→	StatusCheckpointNewer                             // Checkpoint has newer entries
   816→	StatusLocalNewer                                  // Local has newer entries (conflict)
   817→)
   818→
   819→// SessionRestoreInfo contains information about a session being restored.
   820→type SessionRestoreInfo struct {
   821→	SessionID      string
   822→	Prompt         string               // First prompt preview for display
   823→	Status         SessionRestoreStatus // Status of this session
   824→	LocalTime      time.Time
   825→	CheckpointTime time.Time
   826→}
   827→
   828→// classifySessionsForRestore checks all sessions in a checkpoint result and returns info
   829→// about each session, including whether local logs have newer timestamps.
   830→func (s *ManualCommitStrategy) classifySessionsForRestore(claudeProjectDir string, result *cpkg.ReadCommittedResult) []SessionRestoreInfo {
   831→	var sessions []SessionRestoreInfo
   832→
   833→	// Check archived sessions
   834→	for _, archived := range result.ArchivedSessions {
   835→		if len(archived.Transcript) == 0 || archived.SessionID == "" {
   836→			continue
   837→		}
   838→
   839→		modelSessionID := sessionid.ModelSessionID(archived.SessionID)
   840→		localPath := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")
   841→
   842→		localTime := paths.GetLastTimestampFromFile(localPath)
   843→		checkpointTime := paths.GetLastTimestampFromBytes(archived.Transcript)
   844→		status := ClassifyTimestamps(localTime, checkpointTime)
   845→
   846→		sessions = append(sessions, SessionRestoreInfo{
   847→			SessionID:      archived.SessionID,
   848→			Prompt:         ExtractFirstPrompt(archived.Prompts),
   849→			Status:         status,
   850→			LocalTime:      localTime,
   851→			CheckpointTime: checkpointTime,
   852→		})
   853→	}
   854→
   855→	// Check primary session
   856→	if result.Metadata.SessionID != "" && len(result.Transcript) > 0 {
   857→		modelSessionID := sessionid.ModelSessionID(result.Metadata.SessionID)
   858→		localPath := filepath.Join(claudeProjectDir, modelSessionID+".jsonl")
   859→
   860→		localTime := paths.GetLastTimestampFromFile(localPath)
   861→		checkpointTime := paths.GetLastTimestampFromBytes(result.Transcript)
   862→		status := ClassifyTimestamps(localTime, checkpointTime)
   863→
   864→		sessions = append(sessions, SessionRestoreInfo{
   865→			SessionID:      result.Metadata.SessionID,
   866→			Prompt:         ExtractFirstPrompt(result.Prompts),
   867→			Status:         status,
   868→			LocalTime:      localTime,
   869→			CheckpointTime: checkpointTime,
   870→		})
   871→	}
   872→
   873→	return sessions
   874→}
   875→
   876→// ClassifyTimestamps determines the restore status based on local and checkpoint timestamps.
   877→func ClassifyTimestamps(localTime, checkpointTime time.Time) SessionRestoreStatus {
   878→	// Local file doesn't exist (no timestamp found)
   879→	if localTime.IsZero() {
   880→		return StatusNew
   881→	}
   882→
   883→	// Can't determine checkpoint time - treat as new/safe
   884→	if checkpointTime.IsZero() {
   885→		return StatusNew
   886→	}
   887→
   888→	// Compare timestamps
   889→	if localTime.After(checkpointTime) {
   890→		return StatusLocalNewer
   891→	}
   892→	if checkpointTime.After(localTime) {
   893→		return StatusCheckpointNewer
   894→	}
   895→	return StatusUnchanged
   896→}
   897→
   898→// StatusToText returns a human-readable status string.
   899→func StatusToText(status SessionRestoreStatus) string {
   900→	switch status {
   901→	case StatusNew:
   902→		return "(new)"
   903→	case StatusUnchanged:
   904→		return "(unchanged)"
   905→	case StatusCheckpointNewer:
   906→		return "(checkpoint is newer)"
   907→	case StatusLocalNewer:
   908→		return "(local is newer)" // shouldn't appear in non-conflict list
   909→	default:
   910→		return ""
   911→	}
   912→}
   913→
   914→// PromptOverwriteNewerLogs asks the user for confirmation to overwrite local
   915→// session logs that have newer timestamps than the checkpoint versions.
   916→func PromptOverwriteNewerLogs(sessions []SessionRestoreInfo) (bool, error) {
   917→	// Separate conflicting and non-conflicting sessions
   918→	var conflicting, nonConflicting []SessionRestoreInfo
   919→	for _, s := range sessions {
   920→		if s.Status == StatusLocalNewer {
   921→			conflicting = append(conflicting, s)
   922→		} else {
   923→			nonConflicting = append(nonConflicting, s)
   924→		}
   925→	}
   926→
   927→	fmt.Fprintf(os.Stderr, "\nWarning: Local session log(s) have newer entries than the checkpoint:\n")
   928→	for _, info := range conflicting {
   929→		// Show prompt if available, otherwise fall back to session ID
   930→		if info.Prompt != "" {
   931→			fmt.Fprintf(os.Stderr, "  \"%s\"\n", info.Prompt)
   932→		} else {
   933→			fmt.Fprintf(os.Stderr, "  Session: %s\n", info.SessionID)
   934→		}
   935→		fmt.Fprintf(os.Stderr, "    Local last entry:      %s\n", info.LocalTime.Local().Format("2006-01-02 15:04:05"))
   936→		fmt.Fprintf(os.Stderr, "    Checkpoint last entry: %s\n", info.CheckpointTime.Local().Format("2006-01-02 15:04:05"))
   937→	}
   938→
   939→	// Show non-conflicting sessions with their status
   940→	if len(nonConflicting) > 0 {
   941→		fmt.Fprintf(os.Stderr, "\nThese other session(s) will also be restored:\n")
   942→		for _, info := range nonConflicting {
   943→			statusText := StatusToText(info.Status)
   944→			if info.Prompt != "" {
   945→				fmt.Fprintf(os.Stderr, "  \"%s\" %s\n", info.Prompt, statusText)
   946→			} else {
   947→				fmt.Fprintf(os.Stderr, "  Session: %s %s\n", info.SessionID, statusText)
   948→			}
   949→		}
   950→	}
   951→
   952→	fmt.Fprintf(os.Stderr, "\nOverwriting will lose the newer local entries.\n\n")
   953→
   954→	var confirmed bool
   955→	form := huh.NewForm(
   956→		huh.NewGroup(
   957→			huh.NewConfirm().
   958→				Title("Overwrite local session logs with checkpoint versions?").
   959→				Value(&confirmed),
   960→		),
   961→	)
   962→	if isAccessibleMode() {
   963→		form = form.WithAccessible(true)
   964→	}
   965→
   966→	if err := form.Run(); err != nil {
   967→		if errors.Is(err, huh.ErrUserAborted) {
   968→			return false, nil
   969→		}
   970→		return false, fmt.Errorf("failed to get confirmation: %w", err)
   971→	}
   972→
   973→	return confirmed, nil
   974→}
