   102→// CondenseSession condenses a session's shadow branch to permanent storage.
   103→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
   104→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
   105→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
   106→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState) (*CondenseResult, error) {
   107→	// Get shadow branch
   108→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
   109→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   110→	ref, err := repo.Reference(refName, true)
   111→	if err != nil {
   112→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   113→	}
   114→
   115→	// Extract session data from the shadow branch
   116→	// Use tracked files from session state instead of collecting all files from tree
   117→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini)
   118→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType)
   119→	if err != nil {
   120→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   121→	}
   122→
   123→	// Get checkpoint store
   124→	store, err := s.getCheckpointStore()
   125→	if err != nil {
   126→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   127→	}
   128→
   129→	// Get author info
   130→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   131→	attribution := calculateSessionAttributions(repo, ref, sessionData, state)
   132→	// Get current branch name
   133→	branchName := GetCurrentBranchName(repo)
   134→
   135→	// Generate summary if enabled
   136→	var summary *cpkg.Summary
   137→	if settings.IsSummarizeEnabled() && len(sessionData.Transcript) > 0 {
   138→		logCtx := logging.WithComponent(context.Background(), "attribution")
   139→		summarizeCtx := logging.WithComponent(logCtx, "summarize")
   140→
   141→		// Scope transcript to this checkpoint's portion
   142→		scopedTranscript := transcript.SliceFromLine(sessionData.Transcript, state.TranscriptLinesAtStart)
   143→		if len(scopedTranscript) > 0 {
   144→			var err error
   145→			summary, err = summarize.GenerateFromTranscript(summarizeCtx, scopedTranscript, sessionData.FilesTouched, nil)
   146→			if err != nil {
   147→				logging.Warn(summarizeCtx, "summary generation failed",
   148→					slog.String("session_id", state.SessionID),
   149→					slog.String("error", err.Error()))
   150→				// Continue without summary - non-blocking
   151→			} else {
   152→				logging.Info(summarizeCtx, "summary generated",
   153→					slog.String("session_id", state.SessionID))
   154→			}
   155→		}
   156→	}
   157→
   158→	// Write checkpoint metadata using the checkpoint store
   159→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   160→		CheckpointID:                checkpointID,
   161→		SessionID:                   state.SessionID,
   162→		Strategy:                    StrategyNameManualCommit,
   163→		Branch:                      branchName,
   164→		Transcript:                  sessionData.Transcript,
   165→		Prompts:                     sessionData.Prompts,
   166→		Context:                     sessionData.Context,
   167→		FilesTouched:                sessionData.FilesTouched,
   168→		CheckpointsCount:            state.CheckpointCount,
   169→		EphemeralBranch:             shadowBranchName,
   170→		AuthorName:                  authorName,
   171→		AuthorEmail:                 authorEmail,
   172→		Agent:                       state.AgentType,
   173→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
   174→		TranscriptLinesAtStart:      state.TranscriptLinesAtStart,
   175→		TokenUsage:                  sessionData.TokenUsage,
   176→		InitialAttribution:          attribution,
   177→		Summary:                     summary,
   178→	}); err != nil {
   179→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   180→	}
   181→
   182→	return &CondenseResult{
   183→		CheckpointID:         checkpointID,
   184→		SessionID:            state.SessionID,
   185→		CheckpointsCount:     state.CheckpointCount,
   186→		FilesTouched:         sessionData.FilesTouched,
   187→		TotalTranscriptLines: sessionData.FullTranscriptLines,
   188→	}, nil
   189→}
