   191→func calculateSessionAttributions(repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState) *cpkg.InitialAttribution {
   192→	// Calculate initial attribution using accumulated prompt attribution data.
   193→	// This uses user edits captured at each prompt start (before agent works),
   194→	// plus any user edits after the final checkpoint (shadow → head).
   195→	logCtx := logging.WithComponent(context.Background(), "attribution")
   196→	var attribution *cpkg.InitialAttribution
   197→	headRef, headErr := repo.Head()
   198→	if headErr != nil {
   199→		logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
   200→			slog.String("error", headErr.Error()))
   201→	} else {
   202→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
   203→		if commitErr != nil {
   204→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
   205→				slog.String("error", commitErr.Error()))
   206→		} else {
   207→			headTree, treeErr := headCommit.Tree()
   208→			if treeErr != nil {
   209→				logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
   210→					slog.String("error", treeErr.Error()))
   211→			} else {
   212→				// Get shadow branch tree (checkpoint tree - what the agent wrote)
   213→				shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
   214→				if shadowErr != nil {
   215→					logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
   216→						slog.String("error", shadowErr.Error()),
   217→						slog.String("shadow_ref", shadowRef.Hash().String()))
   218→				} else {
   219→					shadowTree, shadowTreeErr := shadowCommit.Tree()
   220→					if shadowTreeErr != nil {
   221→						logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
   222→							slog.String("error", shadowTreeErr.Error()))
   223→					} else {
   224→						// Get base tree (state before session started)
   225→						var baseTree *object.Tree
   226→						if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); baseErr == nil {
   227→							if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
   228→								baseTree = tree
   229→							} else {
   230→								logging.Debug(logCtx, "attribution: base tree unavailable",
   231→									slog.String("error", baseTErr.Error()))
   232→							}
   233→						} else {
   234→							logging.Debug(logCtx, "attribution: base commit unavailable",
   235→								slog.String("error", baseErr.Error()),
   236→								slog.String("base_commit", state.BaseCommit))
   237→						}
   238→
   239→						// Log accumulated prompt attributions for debugging
   240→						var totalUserAdded, totalUserRemoved int
   241→						for i, pa := range state.PromptAttributions {
   242→							totalUserAdded += pa.UserLinesAdded
   243→							totalUserRemoved += pa.UserLinesRemoved
   244→							logging.Debug(logCtx, "prompt attribution data",
   245→								slog.Int("checkpoint", pa.CheckpointNumber),
   246→								slog.Int("user_added", pa.UserLinesAdded),
   247→								slog.Int("user_removed", pa.UserLinesRemoved),
   248→								slog.Int("agent_added", pa.AgentLinesAdded),
   249→								slog.Int("agent_removed", pa.AgentLinesRemoved),
   250→								slog.Int("index", i))
   251→						}
   252→
   253→						attribution = CalculateAttributionWithAccumulated(
   254→							baseTree,
   255→							shadowTree,
   256→							headTree,
   257→							sessionData.FilesTouched,
   258→							state.PromptAttributions,
   259→						)
   260→
   261→						if attribution != nil {
   262→							logging.Info(logCtx, "attribution calculated",
   263→								slog.Int("agent_lines", attribution.AgentLines),
   264→								slog.Int("human_added", attribution.HumanAdded),
   265→								slog.Int("human_modified", attribution.HumanModified),
   266→								slog.Int("human_removed", attribution.HumanRemoved),
   267→								slog.Int("total_committed", attribution.TotalCommitted),
   268→								slog.Float64("agent_percentage", attribution.AgentPercentage),
   269→								slog.Int("accumulated_user_added", totalUserAdded),
   270→								slog.Int("accumulated_user_removed", totalUserRemoved),
   271→								slog.Int("files_touched", len(sessionData.FilesTouched)))
   272→						}
   273→					}
   274→				}
   275→			}
   276→		}
   277→	}
   278→	return attribution
   279→}
