   281→// extractSessionData extracts session data from the shadow branch.
   282→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   283→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
   284→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType agent.AgentType) (*ExtractedSessionData, error) {
   285→	commit, err := repo.CommitObject(shadowRef)
   286→	if err != nil {
   287→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   288→	}
   289→
   290→	tree, err := commit.Tree()
   291→	if err != nil {
   292→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   293→	}
   294→
   295→	data := &ExtractedSessionData{}
   296→	// sessionID is already an "entire session ID" (with date prefix)
   297→	metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
   298→
   299→	// Extract transcript
   300→	// TODO: remove paths.TranscriptFileNameLegacy usage ?
   301→	var fullTranscript string
   302→	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   303→		if content, contentErr := file.Contents(); contentErr == nil {
   304→			fullTranscript = content
   305→		}
   306→	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   307→		if content, contentErr := file.Contents(); contentErr == nil {
   308→			fullTranscript = content
   309→		}
   310→	}
   311→
   312→	// Process transcript based on agent type
   313→	if fullTranscript != "" {
   314→		// Check if this is a Gemini CLI transcript (JSON format, not JSONL)
   315→		isGeminiFormat := agentType == agent.AgentTypeGemini || isGeminiJSONTranscript(fullTranscript)
   316→
   317→		if isGeminiFormat {
   318→			// Gemini uses JSON format with a "messages" array
   319→			data.Transcript = []byte(fullTranscript)
   320→			data.FullTranscriptLines = 1 // JSON is a single "line"
   321→			data.Prompts = extractUserPromptsFromGeminiJSON(fullTranscript)
   322→			data.Context = generateContextFromPrompts(data.Prompts)
   323→		} else {
   324→			// Claude Code and others use JSONL format (one JSON object per line)
   325→			allLines := strings.Split(fullTranscript, "\n")
   326→
   327→			// Trim trailing empty lines (from final \n in JSONL)
   328→			for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   329→				allLines = allLines[:len(allLines)-1]
   330→			}
   331→
   332→			data.FullTranscriptLines = len(allLines)
   333→
   334→			// Always store the full transcript for complete session history
   335→			data.Transcript = []byte(strings.Join(allLines, "\n"))
   336→
   337→			// Extract prompts from the full transcript
   338→			data.Prompts = extractUserPromptsFromLines(allLines)
   339→
   340→			// Generate context from prompts
   341→			data.Context = generateContextFromPrompts(data.Prompts)
   342→		}
   343→	}
   344→
   345→	// Use tracked files from session state (not all files in tree)
   346→	data.FilesTouched = filesTouched
   347→
   348→	// Calculate token usage from the extracted transcript portion
   349→	// TODO: Missing Gemini token usage
   350→	if len(data.Transcript) > 0 {
   351→		// TODO: Calculate token usage per transcript slice (only checkpoint related)
   352→		transcriptLines, err := claudecode.ParseTranscript(data.Transcript)
   353→		if err == nil && len(transcriptLines) > 0 {
   354→			data.TokenUsage = claudecode.CalculateTokenUsage(transcriptLines)
   355→		}
   356→	}
   357→
   358→	return data, nil
   359→}
   360→
   361→// isGeminiJSONTranscript detects if the transcript is in Gemini's JSON format.
   362→// Gemini transcripts start with a JSON object containing a "messages" array.
   363→func isGeminiJSONTranscript(content string) bool {
   364→	content = strings.TrimSpace(content)
   365→	// Quick check: Gemini JSON starts with { and contains "messages"
   366→	if !strings.HasPrefix(content, "{") {
   367→		return false
   368→	}
   369→	// Try to parse as Gemini format
   370→	var transcript struct {
   371→		Messages []json.RawMessage `json:"messages"`
   372→	}
   373→	if err := json.Unmarshal([]byte(content), &transcript); err != nil {
   374→		return false
   375→	}
   376→	return len(transcript.Messages) > 0
   377→}
   378→
   379→// extractUserPromptsFromGeminiJSON extracts user prompts from Gemini's JSON transcript format.
   380→// Gemini transcripts are structured as: {"messages": [{"type": "user", "content": "..."}, ...]}
   381→func extractUserPromptsFromGeminiJSON(content string) []string {
   382→	var transcript struct {
   383→		Messages []struct {
   384→			Type    string `json:"type"`
   385→			Content string `json:"content"`
   386→		} `json:"messages"`
   387→	}
   388→
   389→	if err := json.Unmarshal([]byte(content), &transcript); err != nil {
   390→		return nil
   391→	}
   392→
   393→	var prompts []string
   394→	for _, msg := range transcript.Messages {
   395→		if msg.Type == "user" && msg.Content != "" {
   396→			// Strip IDE context tags for consistency with Claude Code handling
   397→			cleaned := textutil.StripIDEContextTags(msg.Content)
   398→			if cleaned != "" {
   399→				prompts = append(prompts, cleaned)
   400→			}
   401→		}
   402→	}
   403→
   404→	return prompts
   405→}
   406→
   407→// extractUserPromptsFromLines extracts user prompts from JSONL transcript lines.
   408→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   409→func extractUserPromptsFromLines(lines []string) []string {
   410→	var prompts []string
   411→	for _, line := range lines {
   412→		line = strings.TrimSpace(line)
   413→		if line == "" {
   414→			continue
   415→		}
   416→
   417→		var entry map[string]interface{}
   418→		if err := json.Unmarshal([]byte(line), &entry); err != nil {
   419→			continue
   420→		}
   421→
   422→		// Check for user message (supports both "human" and "user" types)
   423→		msgType, ok := entry["type"].(string)
   424→		if !ok || (msgType != "human" && msgType != "user") {
   425→			continue
   426→		}
   427→
   428→		// Extract message content
   429→		message, ok := entry["message"].(map[string]interface{})
   430→		if !ok {
   431→			continue
   432→		}
   433→
   434→		// Handle string content
   435→		if content, ok := message["content"].(string); ok && content != "" {
   436→			cleaned := textutil.StripIDEContextTags(content)
   437→			if cleaned != "" {
   438→				prompts = append(prompts, cleaned)
   439→			}
   440→			continue
   441→		}
   442→
   443→		// Handle array content (e.g., multiple text blocks from VSCode)
   444→		if arr, ok := message["content"].([]interface{}); ok {
   445→			var texts []string
   446→			for _, item := range arr {
   447→				if m, ok := item.(map[string]interface{}); ok {
   448→					if m["type"] == "text" {
   449→						if text, ok := m["text"].(string); ok {
   450→							texts = append(texts, text)
   451→						}
   452→					}
   453→				}
   454→			}
   455→			if len(texts) > 0 {
   456→				cleaned := textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   457→				if cleaned != "" {
   458→					prompts = append(prompts, cleaned)
   459→				}
   460→			}
   461→		}
   462→	}
   463→	return prompts
   464→}
   465→
   466→// generateContextFromPrompts generates context.md content from a list of prompts.
   467→func generateContextFromPrompts(prompts []string) []byte {
   468→	if len(prompts) == 0 {
   469→		return nil
   470→	}
   471→
   472→	var buf strings.Builder
   473→	buf.WriteString("# Session Context\n\n")
   474→	buf.WriteString("## User Prompts\n\n")
   475→
   476→	for i, prompt := range prompts {
   477→		// Truncate very long prompts for readability
   478→		displayPrompt := prompt
   479→		if len(displayPrompt) > 500 {
   480→			displayPrompt = displayPrompt[:500] + "..."
   481→		}
   482→		buf.WriteString(fmt.Sprintf("### Prompt %d\n\n", i+1))
   483→		buf.WriteString(displayPrompt)
   484→		buf.WriteString("\n\n")
   485→	}
   486→
   487→	return []byte(buf.String())
   488→}
