   290→// TestWriteTemporary_Deduplication verifies that WriteTemporary skips creating
   291→// a new commit when the tree hash matches the previous checkpoint.
   292→func TestWriteTemporary_Deduplication(t *testing.T) {
   293→	tempDir := t.TempDir()
   294→
   295→	// Initialize a git repository with an initial commit
   296→	repo, err := git.PlainInit(tempDir, false)
   297→	if err != nil {
