   299→	}
   300→
   301→	// Create worktree and make initial commit
   302→	worktree, err := repo.Worktree()
   303→	if err != nil {
   304→		t.Fatalf("failed to get worktree: %v", err)
   305→	}
   306→
   307→	readmeFile := filepath.Join(tempDir, "README.md")
   308→	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
   309→		t.Fatalf("failed to write README: %v", err)
   310→	}
   311→	if _, err := worktree.Add("README.md"); err != nil {
   312→		t.Fatalf("failed to add README: %v", err)
   313→	}
   314→	initialCommit, err := worktree.Commit("Initial commit", &git.CommitOptions{
   315→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
   316→	})
   317→	if err != nil {
   318→		t.Fatalf("failed to commit: %v", err)
   319→	}
   320→
   321→	// Change to temp dir so paths.RepoRoot() works correctly
   322→	t.Chdir(tempDir)
   323→
   324→	// Create a test file that will be included in checkpoints
   325→	testFile := filepath.Join(tempDir, "test.go")
   326→	if err := os.WriteFile(testFile, []byte("package main\n"), 0o644); err != nil {
   327→		t.Fatalf("failed to write test file: %v", err)
   328→	}
   329→
   330→	// Create metadata directory
   331→	metadataDir := filepath.Join(tempDir, ".entire", "metadata", "test-session")
   332→	if err := os.MkdirAll(metadataDir, 0o755); err != nil {
   333→		t.Fatalf("failed to create metadata dir: %v", err)
   334→	}
   335→	if err := os.WriteFile(filepath.Join(metadataDir, "full.jsonl"), []byte(`{"test": true}`), 0o644); err != nil {
   336→		t.Fatalf("failed to write transcript: %v", err)
   337→	}
   338→
   339→	// Create checkpoint store
   340→	store := NewGitStore(repo)
   341→
   342→	// First checkpoint should be created
   343→	baseCommit := initialCommit.String()
   344→	result1, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   345→		SessionID:         "test-session",
   346→		BaseCommit:        baseCommit,
   347→		ModifiedFiles:     []string{"test.go"},
   348→		MetadataDir:       ".entire/metadata/test-session",
   349→		MetadataDirAbs:    metadataDir,
   350→		CommitMessage:     "Checkpoint 1",
   351→		AuthorName:        "Test",
   352→		AuthorEmail:       "test@test.com",
   353→		IsFirstCheckpoint: true,
   354→	})
   355→	if err != nil {
   356→		t.Fatalf("WriteTemporary() first call error = %v", err)
   357→	}
   358→	if result1.Skipped {
   359→		t.Error("first checkpoint should not be skipped")
   360→	}
   361→	if result1.CommitHash == plumbing.ZeroHash {
   362→		t.Error("first checkpoint should have a commit hash")
   363→	}
   364→
   365→	// Second checkpoint with identical content should be skipped
   366→	result2, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   367→		SessionID:         "test-session",
   368→		BaseCommit:        baseCommit,
   369→		ModifiedFiles:     []string{"test.go"},
