   382→	}
   383→	if result2.CommitHash != result1.CommitHash {
   384→		t.Errorf("skipped checkpoint should return previous commit hash, got %s, want %s",
   385→			result2.CommitHash, result1.CommitHash)
   386→	}
   387→
   388→	// Modify the file and create another checkpoint - should NOT be skipped
   389→	if err := os.WriteFile(testFile, []byte("package main\n\nfunc main() {}\n"), 0o644); err != nil {
   390→		t.Fatalf("failed to modify test file: %v", err)
   391→	}
   392→
   393→	result3, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   394→		SessionID:         "test-session",
   395→		BaseCommit:        baseCommit,
   396→		ModifiedFiles:     []string{"test.go"},
   397→		MetadataDir:       ".entire/metadata/test-session",
   398→		MetadataDirAbs:    metadataDir,
   399→		CommitMessage:     "Checkpoint 3",
   400→		AuthorName:        "Test",
   401→		AuthorEmail:       "test@test.com",
   402→		IsFirstCheckpoint: false,
   403→	})
   404→	if err != nil {
   405→		t.Fatalf("WriteTemporary() third call error = %v", err)
   406→	}
   407→	if result3.Skipped {
   408→		t.Error("third checkpoint with modified content should NOT be skipped")
   409→	}
   410→	if result3.CommitHash == result1.CommitHash {
   411→		t.Error("third checkpoint should have a different commit hash than first")
   412→	}
   413→}
