   611→			t.Fatalf("failed to get HEAD: %v", err)
   612→		}
   613→		if head.Name().IsBranch() {
   614→			t.Fatalf("expected detached HEAD, but on branch %s", head.Name().Short())
   615→		}
   616→
   617→		// Write a committed checkpoint (branch should be empty in detached HEAD)
   618→		checkpointID := id.MustCheckpointID("b2c3d4e5f6a7")
   619→		store := NewGitStore(repo)
   620→		err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
   621→			CheckpointID: checkpointID,
   622→			SessionID:    "test-session-456",
   623→			Strategy:     "manual-commit",
   624→			Branch:       "", // Empty when in detached HEAD
   625→			Transcript:   []byte("test transcript content"),
   626→			AuthorName:   "Test Author",
   627→			AuthorEmail:  "test@example.com",
   628→		})
   629→		if err != nil {
   630→			t.Fatalf("WriteCommitted() error = %v", err)
   631→		}
   632→
   633→		verifyBranchInMetadata(t, repo, checkpointID, "", true)
   634→	})
   635→}
