   734→// TestListCommitted_FallsBackToRemote verifies that ListCommitted can find
   735→// checkpoints when only origin/entire/sessions exists (simulating post-clone state).
   736→func TestListCommitted_FallsBackToRemote(t *testing.T) {
   737→	// Create "remote" repo (non-bare, so we can make commits)
   738→	remoteDir := t.TempDir()
   739→	remoteRepo, err := git.PlainInit(remoteDir, false)
   740→	if err != nil {
   741→		t.Fatalf("failed to init remote repo: %v", err)
   742→	}
   743→
   744→	// Create an initial commit on main branch (required for cloning)
   745→	remoteWorktree, err := remoteRepo.Worktree()
   746→	if err != nil {
   747→		t.Fatalf("failed to get remote worktree: %v", err)
   748→	}
   749→	readmeFile := filepath.Join(remoteDir, "README.md")
   750→	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
   751→		t.Fatalf("failed to write README: %v", err)
   752→	}
   753→	if _, err := remoteWorktree.Add("README.md"); err != nil {
   754→		t.Fatalf("failed to add README: %v", err)
   755→	}
   756→	if _, err := remoteWorktree.Commit("Initial commit", &git.CommitOptions{
   757→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
   758→	}); err != nil {
   759→		t.Fatalf("failed to create initial commit: %v", err)
   760→	}
   761→
   762→	// Create entire/sessions branch on the remote with a checkpoint
   763→	remoteStore := NewGitStore(remoteRepo)
   764→	cpID := id.MustCheckpointID("abcdef123456")
   765→	err = remoteStore.WriteCommitted(context.Background(), WriteCommittedOptions{
   766→		CheckpointID: cpID,
   767→		SessionID:    "test-session-id",
   768→		Strategy:     "manual-commit",
   769→		Transcript:   []byte(`{"test": true}`),
   770→		AuthorName:   "Test",
   771→		AuthorEmail:  "test@test.com",
   772→	})
   773→	if err != nil {
   774→		t.Fatalf("failed to write checkpoint to remote: %v", err)
   775→	}
   776→
   777→	// Clone the repo (this clones main, but not entire/sessions by default)
   778→	localDir := t.TempDir()
   779→	localRepo, err := git.PlainClone(localDir, false, &git.CloneOptions{
   780→		URL: remoteDir,
   781→	})
   782→	if err != nil {
   783→		t.Fatalf("failed to clone repo: %v", err)
   784→	}
   785→
   786→	// Fetch the entire/sessions branch to origin/entire/sessions
   787→	// (but don't create local branch - simulating post-clone state)
   788→	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/origin/%s", paths.MetadataBranchName, paths.MetadataBranchName)
   789→	err = localRepo.Fetch(&git.FetchOptions{
   790→		RemoteName: "origin",
   791→		RefSpecs:   []config.RefSpec{config.RefSpec(refSpec)},
   792→	})
   793→	if err != nil && !errors.Is(err, git.NoErrAlreadyUpToDate) {
   794→		t.Fatalf("failed to fetch entire/sessions: %v", err)
   795→	}
   796→
   797→	// Verify local branch doesn't exist
   798→	_, err = localRepo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
   799→	if err == nil {
   800→		t.Fatal("local entire/sessions branch should not exist")
   801→	}
   802→
   803→	// Verify remote-tracking branch exists
   804→	_, err = localRepo.Reference(plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName), true)
   805→	if err != nil {
   806→		t.Fatalf("origin/entire/sessions should exist: %v", err)
   807→	}
   808→
   809→	// ListCommitted should find the checkpoint by falling back to remote
   810→	localStore := NewGitStore(localRepo)
   811→	checkpoints, err := localStore.ListCommitted(context.Background())
   812→	if err != nil {
   813→		t.Fatalf("ListCommitted() error = %v", err)
   814→	}
   815→	if len(checkpoints) != 1 {
   816→		t.Errorf("ListCommitted() returned %d checkpoints, want 1", len(checkpoints))
   817→	}
   818→	if len(checkpoints) > 0 && checkpoints[0].CheckpointID.String() != cpID.String() {
   819→		t.Errorf("ListCommitted() checkpoint ID = %q, want %q", checkpoints[0].CheckpointID, cpID)
   820→	}
   821→}
